    if (selectionCount < 1)
        return new ActionResult(ActionResult.Status.NoChange, "Set Trigger\nNo objects selected");

    return new ActionResult(ActionResult.Status.Success, "Set Trigger\nSet " + selectionCount + " Objects");
}
